/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: client, mountStart, mountPage, withChanges, applied
 * Tests
 *   - creating a review confirms the frozen Album and only creates a private project without paid analysis
 *   - an Album revision change leaves its open creation approval disabled instead of silently rebasing
 *   - an unconfirmed review creation retries the original UUID and snapshot only when explicitly requested
 *   - reopening and manual editing touch only the private review, preserving catalog projections and identity controls
 *   - Luna analysis requires its own confirmation and a lost acknowledgement never retries automatically
 *   - a durable unknown provider outcome prevents another paid generation while retaining manual review
 *   - Artist-only suggestions explain separate attribution management without offering identity adoption
 *   - a label suggestion is an identity hint beside the Artist hints that can only be kept, while a Disc Number suggestion is a Review item
 *   - a label-only review points Review at its hint, reads a missing label as no value, and a kept hint offers nothing more
 *   - an Artist hint for an Album without Credits context reads the empty baseline and current values as no value
 *   - an applied historical review remains read-only on every stage and never starts work when reopened
 *   - selected suggestion adoption and independent rejection preserve manual values and exclude Artist identity hints
 *   - catalog application confirms only selected saved fields and invalidates projections only after its receipt
 *   - a newer saved revision invalidates an open Apply confirmation rather than rebasing its field selection
 *   - a review saved by a newer release refuses a save with a reload request and no retry
 *   - changing review routes cannot show or retry another project unknown intent
 *   - same-revision refresh and stage changes retain Apply selection, but a newer saved value requires selecting it again
 *   - a delayed successful Save cannot overwrite a newer observed revision or erase its conflict when refresh fails
 *   - analysis progress never makes a local edit stale, while another administrator change does
 *   - completed review guidance is read-only and no longer invites draft editing or a paid run
 *   - the draft shows ordered Credits, join phrases and the label as read-only context and edits Disc Numbers only where captured
 *   - a review opened before Disc Numbers were captured shows no Disc Number input and offers no disc change
 *   - a v1 review response the strict schema refuses asks for a reload instead of showing a partial review
 *   - a captured review saves only changed editable values, never its expected tracklist or member Artist entries
 *   - each save is based on the draft the last save stored, so a second save sends the first saved value as its base
 *   - an edit changed back to the saved value leaves nothing to save
 *   - a save refused because another administrator changed the value reloads the saved review and offers it
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Link, MemoryRouter, Route, Routes } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { CatalogReviewStart } from './CatalogReviewStart';
import { AdminCatalogReviewPage } from './AdminCatalogReviewPage';
import { AdminControls } from './AdminControls';
import type { CatalogReview, ReviewDraftChange, ReviewField } from './catalogReviewApi';
import { artistEntryKey, capturedCatalogReview, catalogAlbum, catalogReview, legacyCatalogReview, otherReviewId, reviewId, reviewJson, session, slotId, titleSuggestionId, trackSuggestionId, viewer } from './catalogReviewFixtures.testSupport';
import styles from './adminStyles';

function client() {
  const value = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  value.setQueryData(['browser-session'], session);
  return value;
}
function mountStart(item = catalogAlbum()) {
  const query = client();
  const wrap = (value: typeof item) => <QueryClientProvider client={query}><MemoryRouter initialEntries={['/admin/catalog']}>
    <Routes><Route path="/admin/catalog" element={<CatalogReviewStart item={value} />} />
      <Route path="/admin/catalog-reviews/:projectId" element={<p>Opened private review</p>} /></Routes>
  </MemoryRouter></QueryClientProvider>;
  const view = render(wrap(item));
  return { query, update: (value: typeof item) => view.rerender(wrap(value)) };
}
function mountPage(controls = false) {
  const query = client();
  render(<QueryClientProvider client={query}><MemoryRouter initialEntries={[`/admin/catalog-reviews/${reviewId}`]}>
    {controls && <AdminControls />}
    <Link to={`/admin/catalog-reviews/${otherReviewId}`}>Other review</Link>
    <Routes><Route path="/admin/catalog-reviews/:reviewId" element={<AdminCatalogReviewPage />} />
      <Route path="/" element={<p>Listener Home</p>} /></Routes>
  </MemoryRouter></QueryClientProvider>);
  return query;
}
/** Writes a per-path save's values into a copy of `draft`, as the server stores an admitted save. */
function withChanges(draft: CatalogReview['draft'], changes: ReviewDraftChange[]): CatalogReview['draft'] {
  const next = structuredClone(draft);
  for (const { path, value } of changes) {
    const [scope, first, second] = path.split('.');
    if (scope === 'album') (next.album as Record<string, unknown>)[first] = value;
    else (next.tracks.find(track => track.slotId === first) as Record<string, unknown>)[second] = value;
  }
  return next;
}
function applied(item: CatalogReview, operationId: string, fields: ReviewField[]): CatalogReview {
  return { ...item, revision: item.revision + 1, state: 'applied', sourceStatus: 'changed', capabilities: { analysis: false, apply: false },
    applied: { operationId, at: '2026-10-02T00:00:00.000Z', fields }, receipts: [{ operationId, revision: item.revision + 1, kind: 'apply' }] };
}

beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('creating a review confirms the frozen Album and only creates a private project without paid analysis', async () => {
  const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    const body = JSON.parse(String(init.body)); writes.push({ path, body });
    return reviewJson({ item: catalogReview(), receipt: { operationId: body.operationId, kind: 'create', revision: 1 } }, 201);
  }));
  mountStart();
  fireEvent.click(screen.getByRole('button', { name: 'Review existing Album' }));
  const dialog = within(screen.getByRole('dialog'));
  expect(dialog.getByText('Synthetic catalog Album')).toBeVisible();
  expect(writes).toEqual([]);
  fireEvent.click(dialog.getByRole('button', { name: 'Create review project' }));
  await screen.findByText('Opened private review');
  expect(writes).toHaveLength(1);
  expect(writes[0]).toMatchObject({ path: '/api/admin/v1/catalog-reviews', body: { albumId: catalogAlbum().id, expectedRevision: catalogAlbum().revision } });
  expect(Object.keys(writes[0].body).sort()).toEqual(['albumId', 'expectedRevision', 'operationId']);
});

test('an Album revision change leaves its open creation approval disabled instead of silently rebasing', () => {
  const fetch = vi.fn(); vi.stubGlobal('fetch', fetch);
  const view = mountStart(); fireEvent.click(screen.getByRole('button', { name: 'Review existing Album' }));
  view.update({ ...catalogAlbum(), revision: `cr_${'b'.repeat(43)}`, fields: { ...catalogAlbum().fields, title: 'A newer synthetic Album title' } });
  const dialog = within(screen.getByRole('dialog'));
  expect(dialog.getByText('Synthetic catalog Album')).toBeVisible();
  expect(dialog.getByRole('button', { name: 'Create review project' })).toBeDisabled();
  fireEvent.click(dialog.getByRole('button', { name: 'Create review project' }));
  expect(fetch).not.toHaveBeenCalled();
});

test.each(['item', 'workspace'] as const)('same-revision editing capability loss from %s blocks an open review creation approval', source => {
  const fetch = vi.fn(); vi.stubGlobal('fetch', fetch);
  const view = mountStart(); fireEvent.click(screen.getByRole('button', { name: 'Review existing Album' }));
  if (source === 'item') view.update({ ...catalogAlbum(), capabilities: { editing: false, visibility: false } });
  else act(() => adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: false, visibility: false }));
  const dialog = within(screen.getByRole('dialog')), confirm = dialog.getByRole('button', { name: 'Create review project' });
  expect(confirm).toBeDisabled(); fireEvent.click(confirm); expect(fetch).not.toHaveBeenCalled();
  expect(screen.getByRole('button', { name: 'Review existing Album' })).toBeDisabled();
  expect(dialog.getByText('Synthetic catalog Album')).toBeVisible();
});

test('an unconfirmed review creation retries the original UUID and snapshot only when explicitly requested', async () => {
  const bodies: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit) => { bodies.push(String(init.body)); throw new TypeError('Synthetic transport loss'); }));
  mountStart(); fireEvent.click(screen.getByRole('button', { name: 'Review existing Album' }));
  fireEvent.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Create review project' }));
  const retry = await screen.findByRole('button', { name: 'Retry original operation' });
  expect(bodies).toHaveLength(1);
  fireEvent.click(retry);
  await waitFor(() => expect(bodies).toHaveLength(2));
  expect(bodies[1]).toBe(bodies[0]);
  expect(JSON.parse(bodies[0])).toMatchObject({ albumId: catalogAlbum().id, expectedRevision: catalogAlbum().revision });
  act(() => adminWorkspace.reset());
  expect(adminWorkspace.buffer(`catalog-review-command:create:${catalogAlbum().id}`)).toBeUndefined();
});

test('reopening and manual editing touch only the private review, preserving catalog projections and identity controls', async () => {
  let item = catalogReview(); const writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    if (init.method === 'PATCH') {
      const body = JSON.parse(String(init.body)); writes.push({ path, body });
      item = { ...item, revision: 2, draft: withChanges(item.draft, body.changes), receipts: [{ operationId: body.operationId, kind: 'edit', revision: 2 }] };
      return reviewJson({ item, receipt: item.receipts[0] });
    }
    return reviewJson({ item, receipt: null });
  }));
  const query = mountPage(); query.setQueryData(['listener', 'album', catalogAlbum().id], { title: 'Cached catalog title' });
  const title = await screen.findByRole('textbox', { name: 'Title' });
  expect(writes).toEqual([]);
  expect(screen.getByRole('textbox', { name: 'Artist name' })).toHaveAttribute('readonly');
  expect(screen.getByText('Artist name (read-only)')).toBeVisible();
  expect(screen.getByRole('link', { name: 'Edit attribution in original Album' })).toHaveAttribute('href', `/admin/catalog/album/${catalogAlbum().id}`);
  expect(screen.getByRole('link', { name: 'Edit visibility in original Album' })).toHaveAttribute('href', `/admin/catalog/album/${catalogAlbum().id}`);
  expect(screen.getByRole('combobox', { name: 'Visibility' })).toBeDisabled();
  expect(screen.getByText('Original filename not retained')).toBeVisible();
  fireEvent.change(title, { target: { value: 'Private human correction' } });
  fireEvent.change(screen.getByRole('spinbutton', { name: '2 · Disc number' }), { target: { value: '2' } });
  expect(screen.getByRole('button', { name: 'Use Luna AI again (paid)' })).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'Save review draft' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Save review draft' })).toBeDisabled());
  // The save sends only the changed values, each with the value it was edited from; the read-only Artist entries, label and
  // visibility are never sent.
  const saved = catalogReview().draft;
  expect(writes[0]).toMatchObject({ path: `/api/admin/v1/catalog-reviews/${reviewId}`, body: { expectedRevision: 1 } });
  expect(Object.keys(writes[0].body).sort()).toEqual(['changes', 'expectedRevision', 'operationId']);
  expect(writes[0].body.changes).toEqual([{ path: 'album.title', base: saved.album.title, value: 'Private human correction' }, { path: `tracks.${saved.tracks[1].slotId}.discNumber`, base: null, value: 2 }]);
  expect(screen.getByRole('textbox', { name: 'Title' })).toHaveValue('Private human correction');
  expect(query.getQueryData(['listener', 'album', catalogAlbum().id])).toEqual({ title: 'Cached catalog title' });
});

test('Luna analysis requires its own confirmation and a lost acknowledgement never retries automatically', async () => {
  const item = catalogReview(); item.analysis = { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }; item.suggestions = [];
  const bodies: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit) => {
    if (init.method === 'POST') { bodies.push(String(init.body)); throw new TypeError('Synthetic connection loss'); }
    return reviewJson({ item, receipt: null });
  }));
  mountPage(); fireEvent.click(await screen.findByRole('button', { name: 'Use Luna AI (paid)' }));
  const dialog = within(await screen.findByRole('dialog', { name: 'Use Luna AI? This is a paid AI service' }));
  expect(dialog.getByText(/It is a paid AI service and may incur a charge/)).toBeVisible();
  expect(bodies).toEqual([]);
  fireEvent.click(dialog.getByRole('button', { name: 'Use Luna AI (paid)' }));
  const retry = await screen.findByRole('button', { name: 'Retry original operation' });
  fireEvent.click(screen.getByRole('tab', { name: 'Review Luna AI suggestions' }));
  fireEvent.click(screen.getByRole('tab', { name: 'Edit draft' }));
  fireEvent.click(screen.getByRole('button', { name: 'Refresh status' }));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Refresh status' })).toBeEnabled());
  expect(bodies).toHaveLength(1);
  fireEvent.click(retry); await waitFor(() => expect(bodies).toHaveLength(2));
  expect(bodies[1]).toBe(bodies[0]);
  expect(JSON.parse(bodies[0])).toMatchObject({ expectedRevision: 1 });
});

test.each([['without saved changes', false], ['with a saved change', true]] as const)('Luna AI is a secondary paid action %s, never the primary one, while its own confirmation keeps a primary confirm', async (_case, changed) => {
  const item = catalogReview(); item.analysis = { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }; item.suggestions = [];
  if (changed) item.draft.album.title = 'Saved Album correction';
  vi.stubGlobal('fetch', vi.fn(async () => reviewJson({ item, receipt: null })));
  mountPage();
  const luna = await screen.findByRole('button', { name: 'Use Luna AI (paid)' });
  expect(luna).not.toHaveClass(styles.primary);
  if (changed) {
    const review = screen.getByRole('button', { name: 'Review changes to apply (1)' });
    expect(review).toHaveClass(styles.primary);
    // The action row keeps its order: Luna AI first, then the primary step to the saved changes.
    expect(luna.compareDocumentPosition(review) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  } else expect(screen.queryByRole('button', { name: /^Review changes to apply/ })).not.toBeInTheDocument();
  fireEvent.click(luna);
  const dialog = within(await screen.findByRole('dialog', { name: 'Use Luna AI? This is a paid AI service' }));
  expect(dialog.getByRole('button', { name: 'Use Luna AI (paid)' })).toHaveClass(styles.primary);
  expect(dialog.getByRole('button', { name: 'Cancel' })).not.toHaveClass(styles.primary);
});

test('a durable unknown provider outcome prevents another paid generation while retaining manual review', async () => {
  const item = catalogReview(); item.analysis = { ...item.analysis, state: 'needsAttention', issue: 'providerOutcomeUnknown' };
  item.suggestions = [];
  const fetch = vi.fn(async (_path: string, _init: RequestInit) => reviewJson({ item, receipt: null })); vi.stubGlobal('fetch', fetch);
  mountPage();
  expect(await screen.findByRole('button', { name: 'Use Luna AI again (paid)' })).toBeDisabled();
  expect(screen.getByRole('textbox', { name: 'Title' })).toBeEnabled();
  expect(screen.queryByRole('button', { name: 'Retry original operation' })).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('tab', { name: 'Review Luna AI suggestions' }));
  expect(await within(screen.getByRole('tabpanel', { name: 'Review Luna AI suggestions' })).findByText('Luna AI needs attention. Check the issue above or continue editing manually.')).toBeVisible();
  expect(fetch.mock.calls.every(([, init]) => !init?.method || init.method === 'GET')).toBe(true);
});

